:root {
  --bg-primary: #0a0e17;
  --bg-secondary: #131a29;
  --bg-card: #182236;
  --bg-hover: #22304c;
  --accent-cyan: #00f2fe;
  --accent-blue: #4facfe;
  --accent-purple: #9d4edd;
  --accent-pink: #f72585;
  --accent-green: #10b981;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border-color: #27354f;
  --glow-shadow: 0 0 20px rgba(0, 242, 254, 0.25);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  min-height: 100vh;
  padding-bottom: 70px;
  overflow-x: hidden;
}

/* App Header */
.app-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 14, 23, 0.92);
  backdrop-filter: blur(12px);
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-color);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-icon {
  font-size: 26px;
  filter: drop-shadow(0 0 8px #00f2fe);
}

.brand-title {
  font-size: 19px;
  font-weight: 800;
  background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.user-profile-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
}

.user-score {
  color: #fbbf24;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Hero Carousel / Featured */
.featured-section {
  padding: 14px 16px;
}

.featured-banner {
  background: linear-gradient(135deg, #1e1b4b 0%, #311042 100%);
  border: 1px solid rgba(157, 78, 221, 0.4);
  border-radius: 16px;
  padding: 18px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 8px 30px rgba(157, 78, 221, 0.2);
}

.featured-banner::after {
  content: "🎮";
  position: absolute;
  right: -10px;
  bottom: -15px;
  font-size: 85px;
  opacity: 0.15;
}

.featured-tag {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--accent-cyan);
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.featured-title {
  font-size: 20px;
  font-weight: 800;
  margin-bottom: 6px;
}

.featured-desc {
  font-size: 12px;
  color: var(--text-muted);
  max-width: 75%;
  margin-bottom: 12px;
  line-height: 1.4;
}

.featured-btn {
  background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
  color: #030712;
  border: none;
  padding: 8px 18px;
  border-radius: 20px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Search Bar */
.search-container {
  padding: 0 16px 10px 16px;
}

.search-bar {
  display: flex;
  align-items: center;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 8px 14px;
  gap: 10px;
}

.search-input {
  background: transparent;
  border: none;
  outline: none;
  color: #fff;
  font-size: 14px;
  width: 100%;
}

.search-input::placeholder {
  color: var(--text-muted);
}

/* Category Filter Tabs */
.categories-tabs {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 6px 16px 12px 16px;
  scrollbar-width: none;
}
.categories-tabs::-webkit-scrollbar { display: none; }

.cat-tab {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 7px 14px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s ease;
}

.cat-tab.active {
  background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
  color: #040814;
  border-color: transparent;
  font-weight: 700;
}

/* Stats Counter */
.section-header {
  padding: 0 16px 8px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-title {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
}

.catalog-counter {
  font-size: 12px;
  color: var(--accent-cyan);
  background: rgba(0, 242, 254, 0.1);
  padding: 2px 8px;
  border-radius: 10px;
}

/* Game Cards Grid */
.games-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 12px;
  padding: 0 16px 20px 16px;
}

.game-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.15s, border-color 0.15s;
  cursor: pointer;
  position: relative;
}

.game-card:active {
  transform: scale(0.97);
}

.game-thumb-box {
  width: 100%;
  height: 100px;
  background: linear-gradient(135deg, #1e293b, #0f172a);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 42px;
  position: relative;
  overflow: hidden;
}

.game-badge {
  position: absolute;
  top: 6px;
  left: 6px;
  font-size: 9px;
  font-weight: 800;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(4px);
  color: #38bdf8;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid rgba(56, 189, 248, 0.3);
}

.fav-btn {
  position: absolute;
  top: 6px;
  right: 6px;
  background: rgba(15, 23, 42, 0.75);
  border: none;
  font-size: 14px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.fav-btn.active {
  color: #f43f5e;
}

.game-info {
  padding: 10px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.game-title {
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 4px;
}

.game-meta {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.game-rating {
  color: #fbbf24;
}

.play-action-btn {
  margin-top: auto;
  background: var(--bg-hover);
  border: 1px solid var(--border-color);
  color: #38bdf8;
  padding: 6px 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  text-align: center;
  transition: background 0.15s;
}

.play-action-btn:hover {
  background: var(--accent-blue);
  color: #000;
}

/* Bottom Navigation Bar */
.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60px;
  background: rgba(10, 14, 23, 0.96);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-around;
  align-items: center;
  z-index: 99;
}

.nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  background: none;
  border: none;
  cursor: pointer;
}

.nav-item.active {
  color: var(--accent-cyan);
}

.nav-icon {
  font-size: 20px;
}

/* Modal Player */
.game-modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #000;
  z-index: 200;
  flex-direction: column;
}

.game-modal.open {
  display: flex;
}

.modal-bar {
  height: 48px;
  background: #0a0e17;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 14px;
}

.modal-title {
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 60%;
}

.modal-actions {
  display: flex;
  gap: 10px;
}

.modal-btn {
  background: #1e293b;
  border: 1px solid #334155;
  color: #fff;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.modal-btn.close {
  background: #dc2626;
  border-color: #ef4444;
}

.modal-frame {
  flex-grow: 1;
  width: 100%;
  border: none;
  background: #090d16;
}

/* Leaderboard Modal / View */
.view-modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 60px;
  background: var(--bg-primary);
  z-index: 110;
  overflow-y: auto;
  padding: 20px 16px;
}

.view-modal.open {
  display: block;
}

.leader-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  padding: 12px 16px;
  border-radius: 12px;
  margin-bottom: 10px;
}

.leader-rank {
  font-size: 18px;
  font-weight: 800;
  width: 32px;
  color: var(--accent-cyan);
}

.leader-name {
  font-weight: 700;
  font-size: 14px;
  flex-grow: 1;
}

.leader-score {
  font-weight: 800;
  color: #fbbf24;
  font-size: 15px;
}

/* Empty State / Loading */
.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: var(--text-muted);
}

// Telegram Game Hub - WebApp Frontend Engine
const tg = window.Telegram?.WebApp;
if (tg) {
  tg.ready();
  tg.expand();
  if (tg.enableClosingConfirmation) tg.enableClosingConfirmation();
}

// User state
const currentUser = {
  id: tg?.initDataUnsafe?.user?.id || 10001,
  first_name: tg?.initDataUnsafe?.user?.first_name || 'Player',
  username: tg?.initDataUnsafe?.user?.username || 'player_one',
  totalScore: 0,
  rank: 1,
  gamesPlayed: 0
};

// State variables
let allGames = [];
let filteredGames = [];
let currentCategory = 'all';
let searchQuery = '';
let renderedCount = 0;
const BATCH_SIZE = 36;
let favorites = JSON.parse(localStorage.getItem('game_favorites') || '[]');
let activeGame = null;

// Category Emojis
const categoryIcons = {
  'Arcade': '🕹️',
  'Puzzle': '🧩',
  'Action': '⚔️',
  'Racing': '🏎️',
  'Sports': '⚽',
  'Retro': '👾',
  'Cards & Board': '🃏',
  'Casual': '🎯'
};

// Initialize UI
document.addEventListener('DOMContentLoaded', async () => {
  setupHeader();
  setupEventListeners();
  await loadGames();
  await loadUserProfile();
});

function setupHeader() {
  document.getElementById('header-user-name').innerText = currentUser.first_name;
  document.getElementById('prof-user-name').innerText = currentUser.first_name;
  document.getElementById('prof-user-id').innerText = `ID: ${currentUser.id} (@${currentUser.username})`;
}

async function loadGames() {
  try {
    const res = await fetch('/api/games?limit=1000');
    const data = await res.json();
    allGames = data.games || [];
    filterAndRender();
  } catch (err) {
    console.error('Failed to load games:', err);
    document.getElementById('games-grid').innerHTML = '<div class="empty-state">Failed to load games. Please refresh.</div>';
  }
}

async function loadUserProfile() {
  try {
    const res = await fetch(`/api/user/${currentUser.id}/stats?first_name=${encodeURIComponent(currentUser.first_name)}&username=${encodeURIComponent(currentUser.username)}`);
    const data = await res.json();
    if (data) {
      currentUser.totalScore = data.total_score || 0;
      currentUser.rank = data.rank || 1;
      currentUser.gamesPlayed = data.total_games_played || 0;

      document.getElementById('header-user-score').innerText = currentUser.totalScore;
      document.getElementById('prof-total-score').innerText = currentUser.totalScore;
      document.getElementById('prof-rank').innerText = `#${currentUser.rank}`;
      document.getElementById('prof-played').innerText = currentUser.gamesPlayed;
    }
  } catch (e) {
    console.warn('Could not fetch user profile:', e);
  }
}

function filterAndRender() {
  filteredGames = allGames.filter(g => {
    const matchCat = currentCategory === 'all' || g.category === currentCategory;
    const matchSearch = !searchQuery || 
      g.title.toLowerCase().includes(searchQuery) || 
      g.category.toLowerCase().includes(searchQuery) ||
      (g.tags && g.tags.some(t => t.toLowerCase().includes(searchQuery)));
    return matchCat && matchSearch;
  });

  const grid = document.getElementById('games-grid');
  grid.innerHTML = '';
  renderedCount = 0;

  document.getElementById('game-counter').innerText = `${filteredGames.length.toLocaleString()} Games`;
  const secTitle = currentCategory === 'all' ? 'All Games' : `${currentCategory} Games`;
  document.getElementById('current-section-title').innerText = searchQuery ? `Search: "${searchQuery}"` : secTitle;

  renderBatch();
}

function renderBatch() {
  const grid = document.getElementById('games-grid');
  const nextSlice = filteredGames.slice(renderedCount, renderedCount + BATCH_SIZE);

  if (filteredGames.length === 0) {
    grid.innerHTML = '<div class="empty-state" style="grid-column: 1/-1;">No games found matching your search.</div>';
    document.getElementById('load-more-btn').style.display = 'none';
    return;
  }

  const fragment = document.createDocumentFragment();
  nextSlice.forEach(game => {
    const card = createGameCard(game);
    fragment.appendChild(card);
  });
  grid.appendChild(fragment);

  renderedCount += nextSlice.length;

  const loadMoreBtn = document.getElementById('load-more-btn');
  if (renderedCount < filteredGames.length) {
    loadMoreBtn.style.display = 'inline-block';
    loadMoreBtn.innerText = `Load More (${filteredGames.length - renderedCount} remaining) ⬇`;
  } else {
    loadMoreBtn.style.display = 'none';
  }
}

function createGameCard(game) {
  const card = document.createElement('div');
  card.className = 'game-card';
  card.onclick = () => openGame(game.id);

  const icon = categoryIcons[game.category] || '🎮';
  const isFav = favorites.includes(game.id);

  card.innerHTML = `
    <div class="game-thumb-box">
      <span>${icon}</span>
      ${game.badge ? `<div class="game-badge">${game.badge}</div>` : ''}
      <button class="fav-btn ${isFav ? 'active' : ''}" onclick="toggleFav(event, '${game.id}')">
        ${isFav ? '❤️' : '🤍'}
      </button>
    </div>
    <div class="game-info">
      <div class="game-title" title="${game.title}">${game.title}</div>
      <div class="game-meta">
        <span class="game-rating">★ ${game.rating}</span>
        <span>${formatNumber(game.plays)} plays</span>
      </div>
      <div class="play-action-btn">▶ PLAY</div>
    </div>
  `;
  return card;
}

function formatNumber(num) {
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
  return num;
}

function toggleFav(e, gameId) {
  e.stopPropagation();
  if (favorites.includes(gameId)) {
    favorites = favorites.filter(id => id !== gameId);
  } else {
    favorites.push(gameId);
  }
  localStorage.setItem('game_favorites', JSON.stringify(favorites));
  if (tg?.HapticFeedback) tg.HapticFeedback.selectionChanged();

  // Re-render fav button
  filterAndRender();

  // Inform backend
  fetch('/api/favorite', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ user_id: currentUser.id, game_id: gameId })
  }).catch(() => {});
}

// Game Player
function openGame(gameId) {
  const game = allGames.find(g => g.id === gameId);
  if (!game) return;

  activeGame = game;
  const modal = document.getElementById('game-modal');
  const iframe = document.getElementById('game-iframe');
  document.getElementById('modal-game-title').innerText = game.title;

  iframe.src = game.builtin_path;
  modal.classList.add('open');

  if (tg?.HapticFeedback) tg.HapticFeedback.impactOccurred('medium');

  // Increment play count
  fetch(`/api/games/${gameId}/play`, { method: 'POST' }).catch(() => {});
}

function closeGame() {
  const modal = document.getElementById('game-modal');
  const iframe = document.getElementById('game-iframe');
  iframe.src = '';
  modal.classList.remove('open');
  activeGame = null;
  loadUserProfile(); // Refresh score
}

function shareCurrentGame() {
  if (!activeGame) return;
  const shareText = `🎮 Play ${activeGame.title} on Telegram Game Hub! Can you beat my high score?`;
  const shareUrl = `https://t.me/share/url?url=${encodeURIComponent(window.location.origin)}&text=${encodeURIComponent(shareText)}`;

  if (tg?.openTelegramLink) {
    tg.openTelegramLink(shareUrl);
  } else {
    window.open(shareUrl, '_blank');
  }
}

// Listen for score events from embedded games
window.addEventListener('message', async (e) => {
  if (e.data && e.data.type === 'SCORE_UPDATE') {
    const { gameId, score } = e.data;
    console.log(`Received score update for ${gameId}: ${score}`);

    try {
      const res = await fetch('/api/score', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user_id: currentUser.id,
          username: currentUser.username,
          first_name: currentUser.first_name,
          game_id: gameId,
          score: score
        })
      });
      const data = await res.json();
      if (data.is_new_high_score && tg?.showAlert) {
        tg.showAlert(`🎉 NEW HIGH SCORE: ${score} in ${activeGame?.title || 'the game'}!`);
      }
      loadUserProfile();
    } catch (err) {
      console.error('Failed to submit score:', err);
    }
  }
});

// Navigation switches
function switchNav(tab) {
  document.querySelectorAll('.nav-item').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.view-modal').forEach(m => m.classList.remove('open'));

  const navBtn = document.getElementById(`nav-${tab}`);
  if (navBtn) navBtn.classList.add('active');

  if (tab === 'games') {
    document.getElementById('main-view').style.display = 'block';
  } else {
    document.getElementById('main-view').style.display = 'none';
    const viewModal = document.getElementById(`${tab}-view`);
    if (viewModal) viewModal.classList.add('open');

    if (tab === 'leaderboard') renderLeaderboard();
    if (tab === 'favorites') renderFavorites();
    if (tab === 'profile') loadUserProfile();
  }
}

async function renderLeaderboard() {
  const container = document.getElementById('leaderboard-list');
  container.innerHTML = '<div class="empty-state">Loading top players...</div>';
  try {
    const res = await fetch('/api/leaderboard');
    const data = await res.json();
    const leaders = data.leaderboard || [];

    if (leaders.length === 0) {
      container.innerHTML = '<div class="empty-state">No scores yet. Be the first to play and rank #1!</div>';
      return;
    }

    container.innerHTML = leaders.map((u, i) => {
      let rankMedal = `#${i + 1}`;
      if (i === 0) rankMedal = '🥇 1';
      else if (i === 1) rankMedal = '🥈 2';
      else if (i === 2) rankMedal = '🥉 3';

      return `
        <div class="leader-item">
          <div class="leader-rank">${rankMedal}</div>
          <div class="leader-name">${u.first_name || u.username || 'Anonymous Player'}</div>
          <div class="leader-score">⭐ ${u.total_score.toLocaleString()}</div>
        </div>
      `;
    }).join('');
  } catch (e) {
    container.innerHTML = '<div class="empty-state">Failed to load leaderboard.</div>';
  }
}

function renderFavorites() {
  const container = document.getElementById('favorites-grid');
  const favGames = allGames.filter(g => favorites.includes(g.id));

  if (favGames.length === 0) {
    container.innerHTML = '<div class="empty-state" style="grid-column: 1/-1;">You have not favorited any games yet.<br>Tap the ❤️ icon on any game to save it here!</div>';
    return;
  }

  container.innerHTML = '';
  favGames.forEach(game => {
    container.appendChild(createGameCard(game));
  });
}

// Event Listeners
function setupEventListeners() {
  // Category tabs
  const tabs = document.querySelectorAll('.cat-tab');
  tabs.forEach(tab => {
    tab.onclick = () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentCategory = tab.dataset.cat;
      filterAndRender();
      if (tg?.HapticFeedback) tg.HapticFeedback.selectionChanged();
    };
  });

  // Search input with debounce
  const searchInput = document.getElementById('search-input');
  const searchClear = document.getElementById('search-clear');

  let debounceTimer = null;
  searchInput.addEventListener('input', (e) => {
    clearTimeout(debounceTimer);
    searchQuery = e.target.value.trim().toLowerCase();
    searchClear.style.display = searchQuery ? 'block' : 'none';

    debounceTimer = setTimeout(() => {
      filterAndRender();
    }, 200);
  });

  searchClear.onclick = () => {
    searchInput.value = '';
    searchQuery = '';
    searchClear.style.display = 'none';
    filterAndRender();
  };

  // Load more button
  document.getElementById('load-more-btn').onclick = () => {
    renderBatch();
  };

  // Infinite scroll
  window.addEventListener('scroll', () => {
    if (window.innerHeight + window.scrollY >= document.body.offsetHeight - 500) {
      if (renderedCount < filteredGames.length) {
        renderBatch();
      }
    }
  });
}

"""
Inline and Reply Keyboards for the Telegram Game Bot.
Supports Telegram Mini App WebApp buttons and interactive menu navigation.
"""
from aiogram.types import InlineKeyboardMarkup, InlineKeyboardButton, WebAppInfo
from config import WEBAPP_URL

def get_main_menu_keyboard() -> InlineKeyboardMarkup:
